import * as THREE from 'three';

export type HeroPose = 'idle' | 'walk' | 'run' | 'jump' | 'fall' | 'land' | 'attack' | 'dodge' | 'guard' | 'cast' | 'hit' | 'defeat' | 'fly';
export type HeroRig = { root: THREE.Group; spellPoint: THREE.Object3D; update: (time: number, delta: number, pose: HeroPose, speed?: number) => void };

function mesh(geometry: THREE.BufferGeometry, material: THREE.Material, parent: THREE.Object3D, position: [number, number, number] = [0, 0, 0]) {
  const object = new THREE.Mesh(geometry, material);
  object.position.set(...position); object.castShadow = true; object.receiveShadow = true; parent.add(object);
  return object;
}

function capsule(material: THREE.Material, radius: number, length: number, parent: THREE.Object3D, position: [number, number, number] = [0, 0, 0]) {
  return mesh(new THREE.CapsuleGeometry(radius, length, 5, 10), material, parent, position);
}

function smoothAngle(current: number, target: number, amount: number) {
  const difference = THREE.MathUtils.euclideanModulo(target - current + Math.PI, Math.PI * 2) - Math.PI;
  return current + difference * amount;
}

export function createHero(scene: THREE.Scene): HeroRig {
  const root = new THREE.Group(); root.name = 'called-wanderer';
  const body = new THREE.Group(); body.name = 'provisional-articulated-rig'; root.add(body);
  const toonRamp = new THREE.DataTexture(new Uint8Array([22, 86, 158, 232]), 4, 1, THREE.RedFormat);
  toonRamp.magFilter = THREE.NearestFilter; toonRamp.minFilter = THREE.NearestFilter; toonRamp.generateMipmaps = false; toonRamp.needsUpdate = true;
  const toon = (color: string) => new THREE.MeshToonMaterial({ color, gradientMap: toonRamp });
  scene.userData.gameTextures = [...(scene.userData.gameTextures ?? []), toonRamp];
  const cloth = toon('#42616a');
  const coat = toon('#dad1b7');
  const coatShadow = toon('#a5a18c');
  const leather = toon('#544337');
  const metal = new THREE.MeshStandardMaterial({ color: '#b99d67', roughness: .43, metalness: .42 });
  const skin = toon('#edc9a9');
  const hair = toon('#e4e1d3');
  const hairShade = toon('#aeb9b5');
  const eye = toon('#6f998e');
  const glow = new THREE.MeshToonMaterial({ color: '#f2dca5', emissive: '#b58a3f', emissiveIntensity: 1.2, gradientMap: toonRamp });

  const torso = mesh(new THREE.CapsuleGeometry(.38, .62, 7, 14), cloth, body, [0, 1.43, 0]); torso.scale.set(1, 1, .78);
  const mantle = new THREE.Mesh(new THREE.LatheGeometry([
    new THREE.Vector2(.54, .12), new THREE.Vector2(.58, .22), new THREE.Vector2(.49, .5),
    new THREE.Vector2(.39, .82), new THREE.Vector2(.4, 1.13), new THREE.Vector2(.53, 1.43),
    new THREE.Vector2(.45, 1.58), new THREE.Vector2(.28, 1.65),
  ], 16), coat);
  mantle.position.set(0, .25, -.035); mantle.castShadow = true; mantle.receiveShadow = true; body.add(mantle);
  for (const side of [-1, 1]) {
    const seamCurve = new THREE.CatmullRomCurve3([
      new THREE.Vector3(side * .15, 1.82, -.31), new THREE.Vector3(side * .2, 1.35, -.48),
      new THREE.Vector3(side * .26, .85, -.51), new THREE.Vector3(side * .45, .38, -.57),
    ]);
    mesh(new THREE.TubeGeometry(seamCurve, 18, .012, 5, false), coatShadow, body);
  }
  const mantlePanel = mesh(new THREE.BufferGeometry(), coatShadow, body);
  const panelShape = new THREE.Shape(); panelShape.moveTo(-.09, 1.38); panelShape.lineTo(.3, 1.42); panelShape.lineTo(.44, .12); panelShape.lineTo(.16, .04); panelShape.closePath();
  mantlePanel.geometry.dispose(); mantlePanel.geometry = new THREE.ShapeGeometry(panelShape, 1); mantlePanel.position.set(.04, .25, .37);
  const collar = mesh(new THREE.TorusGeometry(.39, .095, 9, 20, Math.PI), coat, body, [0, 2.02, 0]); collar.rotation.z = Math.PI;
  const scarf = mesh(new THREE.TorusGeometry(.36, .1, 8, 24), cloth, body, [0, 1.89, .015]); scarf.rotation.x = Math.PI / 2;

  const head = new THREE.Group(); head.position.set(0, 2.13, .015); body.add(head);
  const face = mesh(new THREE.SphereGeometry(.31, 20, 18), skin, head, [0, .04, .015]); face.scale.set(.92, 1.08, .83);
  for (const side of [-1, 1]) {
    const ear = mesh(new THREE.SphereGeometry(.09, 12, 10), skin, head, [side * .29, .045, -.005]); ear.scale.set(.55, 1.18, .68);
    const eyeWhite = mesh(new THREE.SphereGeometry(.052, 10, 10), new THREE.MeshBasicMaterial({ color: '#f7f0df' }), head, [side * .112, .065, .268]); eyeWhite.scale.set(1.15, .82, .45);
    mesh(new THREE.SphereGeometry(.028, 10, 8), eye, head, [side * .112, .065, .29]);
    const brow = mesh(new THREE.CapsuleGeometry(.018, .075, 2, 6), hairShade, head, [side * .11, .145, .25]); brow.rotation.z = side * -.12; brow.rotation.y = side * -.08;
  }
  mesh(new THREE.SphereGeometry(.025, 9, 7), skin, head, [0, -.025, .277]);
  const fringe = mesh(new THREE.SphereGeometry(.31, 18, 12, 0, Math.PI * 2, 0, Math.PI * .62), hair, head, [0, .17, -.018]); fringe.scale.set(1.1, 1.05, 1);
  for (let i = 0; i < 7; i++) {
    const side = i % 2 ? 1 : -1;
    const lock = mesh(new THREE.CapsuleGeometry(.065, .2 + (i % 3) * .035, 4, 8), i % 3 === 0 ? hairShade : hair, head,
      [side * (.1 + Math.floor(i / 2) * .055), -.02 - (i % 3) * .045, .18 - Math.floor(i / 2) * .045]);
    lock.rotation.z = side * (.25 + (i % 3) * .12); lock.rotation.x = .18;
  }
  for (let i = 0; i < 6; i++) {
    const x = (i - 2.5) * .085;
    const length = .21 + (i % 3) * .07;
    const backLock = capsule(i % 2 ? hair : hairShade, .047, length + .08, head, [x, -.14 - length * .34, -.19]);
    backLock.scale.set(.92, 1.08, .68);
    backLock.rotation.z = x * -.42;
  }
  for (const side of [-1, 1]) {
    const sideLock = capsule(hair, .07, .22, head, [side * .265, -.11, -.02]);
    sideLock.scale.set(.82, 1.25, .74); sideLock.rotation.z = side * .1;
  }
  const circlet = mesh(new THREE.TorusGeometry(.255, .028, 7, 24, Math.PI), metal, head, [0, .27, .005]); circlet.rotation.z = Math.PI;
  const circletGem = mesh(new THREE.OctahedronGeometry(.065, 0), glow, head, [0, .48, .015]); circletGem.scale.set(.76, 1.28, .62);

  const hips = new THREE.Group(); hips.position.set(0, .73, 0); body.add(hips);
  const legs: THREE.Group[] = [];
  for (const side of [-1, 1]) {
    const thigh = new THREE.Group(); thigh.name = side < 0 ? 'leg-left' : 'leg-right'; thigh.position.set(side * .19, 0, 0); hips.add(thigh); legs.push(thigh);
    capsule(leather, .13, .33, thigh, [0, -.31, 0]);
    const shin = new THREE.Group(); shin.position.set(0, -.57, 0); thigh.add(shin);
    capsule(coatShadow, .12, .3, shin, [0, -.22, 0]);
    const boot = mesh(new THREE.CapsuleGeometry(.14, .2, 4, 9), leather, shin, [0, -.49, .075]); boot.rotation.x = Math.PI / 2;
    const bootTrim = mesh(new THREE.TorusGeometry(.122, .025, 6, 12), metal, shin, [0, -.34, 0]); bootTrim.rotation.x = Math.PI / 2;
  }

  const arms: THREE.Group[] = [];
  for (const side of [-1, 1]) {
    const shoulder = mesh(new THREE.SphereGeometry(.2, 12, 10), coatShadow, body, [side * .43, 1.79, 0]); shoulder.scale.set(1.06, .74, .83);
    const arm = new THREE.Group(); arm.name = side < 0 ? 'arm-left' : 'arm-right'; arm.position.set(side * .46, 1.78, .01); body.add(arm); arms.push(arm);
    capsule(cloth, .115, .31, arm, [0, -.25, 0]);
    const cuff = mesh(new THREE.TorusGeometry(.12, .024, 6, 12), metal, arm, [0, -.48, 0]);
    capsule(coat, .095, .26, arm, [0, -.64, 0]);
    mesh(new THREE.SphereGeometry(.11, 10, 8), leather, arm, [0, -.84, .025]);
    cuff.position.y = -.48;
  }

  const belt = mesh(new THREE.TorusGeometry(.35, .055, 8, 24), leather, body, [0, .99, 0]); belt.rotation.x = Math.PI / 2;
  const clasp = mesh(new THREE.BoxGeometry(.16, .14, .055), metal, body, [0, .99, .36]);
  const satchel = mesh(new THREE.BoxGeometry(.24, .27, .13), leather, body, [-.42, 1.05, .04]); satchel.rotation.z = -.14;
  const strap = mesh(new THREE.CapsuleGeometry(.025, .72, 4, 7), leather, body, [-.22, 1.48, -.06]); strap.rotation.z = -.32; strap.rotation.x = -.2;

  const staff = new THREE.Group(); staff.name = 'heirloom-staff'; staff.position.set(.52, .67, .15); staff.rotation.z = -.11; body.add(staff);
  const wood = new THREE.MeshStandardMaterial({ color: '#644b35', roughness: .83 });
  const shaft = mesh(new THREE.CylinderGeometry(.038, .065, 2.2, 9), wood, staff, [0, .66, 0]);
  const grip = mesh(new THREE.CapsuleGeometry(.07, .2, 4, 8), leather, staff, [0, .48, .02]);
  for (let i = 0; i < 3; i++) {
    const wrap = mesh(new THREE.TorusGeometry(.055, .018, 6, 10), metal, staff, [0, .35 + i * .12, 0]); wrap.rotation.x = Math.PI / 2;
  }
  const headRing = mesh(new THREE.TorusGeometry(.15, .035, 8, 18), metal, staff, [0, 1.87, 0]); headRing.rotation.x = Math.PI / 2;
  const focus = mesh(new THREE.IcosahedronGeometry(.115, 1), glow, staff, [0, 1.87, 0]);
  const spellPoint = new THREE.Object3D(); spellPoint.position.set(0, 1.91, .04); staff.add(spellPoint);
  const aura = new THREE.PointLight('#efdba9', .85, 4, 2); aura.position.set(0, 1.9, .1); staff.add(aura);
  root.userData = { body, legs, arms, focus, clasp, satchel, shoulder: root };
  root.position.set(0, 0, 2);
  scene.add(root);

  const mixer = new THREE.AnimationMixer(root);
  const keyTimes = new Float32Array([0, .25, .5, .75, 1]);
  const makeTrack = (target: string, property: string, values: number[]) => new THREE.NumberKeyframeTrack(`${target}.${property}`, keyTimes, values);
  const clips = new Map<HeroPose, THREE.AnimationAction>();
  const clipData: Record<HeroPose, { duration: number; tracks: THREE.KeyframeTrack[]; loop?: boolean }> = {
    idle: { duration: 1, tracks: [makeTrack('provisional-articulated-rig', 'position[y]', [0, .018, .035, .018, 0]), makeTrack('arm-left', 'rotation[x]', [-.025, -.04, -.025, -.01, -.025]), makeTrack('arm-right', 'rotation[x]', [-.025, -.01, -.025, -.04, -.025]) ] },
    walk: { duration: .78, tracks: [makeTrack('leg-left', 'rotation[x]', [.38, 0, -.38, 0, .38]), makeTrack('leg-right', 'rotation[x]', [-.38, 0, .38, 0, -.38]), makeTrack('arm-left', 'rotation[x]', [-.19, 0, .19, 0, -.19]), makeTrack('arm-right', 'rotation[x]', [.19, 0, -.19, 0, .19]), makeTrack('provisional-articulated-rig', 'position[y]', [.015, .055, .015, .055, .015]) ] },
    run: { duration: .52, tracks: [makeTrack('leg-left', 'rotation[x]', [.62, 0, -.62, 0, .62]), makeTrack('leg-right', 'rotation[x]', [-.62, 0, .62, 0, -.62]), makeTrack('arm-left', 'rotation[x]', [-.34, 0, .34, 0, -.34]), makeTrack('arm-right', 'rotation[x]', [.34, 0, -.34, 0, .34]), makeTrack('provisional-articulated-rig', 'position[y]', [.025, .11, .025, .11, .025]), makeTrack('provisional-articulated-rig', 'rotation[z]', [-.025, 0, .025, 0, -.025]) ] },
    jump: { duration: .48, loop: false, tracks: [makeTrack('leg-left', 'rotation[x]', [-.24, -.35, -.26, -.2, -.2]), makeTrack('leg-right', 'rotation[x]', [-.24, -.18, -.25, -.22, -.2]), makeTrack('arm-left', 'rotation[x]', [-.2, -.55, -.48, -.5, -.5]), makeTrack('arm-right', 'rotation[x]', [-.2, -.55, -.48, -.5, -.5]), makeTrack('provisional-articulated-rig', 'position[y]', [0, .12, .13, .08, .05]) ] },
    fall: { duration: 1, tracks: [makeTrack('leg-left', 'rotation[x]', [-.2, -.18, -.22, -.18, -.2]), makeTrack('leg-right', 'rotation[x]', [-.2, -.22, -.18, -.22, -.2]), makeTrack('arm-left', 'rotation[x]', [-.25, -.2, -.25, -.2, -.25]), makeTrack('arm-right', 'rotation[x]', [-.25, -.2, -.25, -.2, -.25]), makeTrack('provisional-articulated-rig', 'rotation[z]', [.04, .025, .04, .025, .04]) ] },
    land: { duration: .42, loop: false, tracks: [makeTrack('leg-left', 'rotation[x]', [-.28, -.48, -.24, 0, 0]), makeTrack('leg-right', 'rotation[x]', [-.28, -.42, -.2, 0, 0]), makeTrack('provisional-articulated-rig', 'position[y]', [.04, -.1, -.03, 0, 0])] },
    attack: { duration: .36, loop: false, tracks: [makeTrack('arm-left', 'rotation[x]', [-.1, -.78, -.46, -.08, -.08]), makeTrack('arm-right', 'rotation[x]', [-.1, -.92, -.35, -.08, -.08]), makeTrack('provisional-articulated-rig', 'rotation[z]', [0, -.08, .12, 0, 0])] },
    dodge: { duration: .42, loop: false, tracks: [makeTrack('leg-left', 'rotation[x]', [-.12, -.65, -.3, 0, 0]), makeTrack('leg-right', 'rotation[x]', [-.12, .3, .6, 0, 0]), makeTrack('arm-left', 'rotation[x]', [-.1, -.35, -.5, -.1, -.1]), makeTrack('arm-right', 'rotation[x]', [-.1, -.5, -.35, -.1, -.1]), makeTrack('provisional-articulated-rig', 'rotation[z]', [0, -.3, .25, 0, 0])] },
    guard: { duration: 1, tracks: [makeTrack('arm-left', 'rotation[x]', [-.5, -.52, -.5, -.48, -.5]), makeTrack('arm-right', 'rotation[x]', [-.65, -.68, -.65, -.63, -.65])] },
    cast: { duration: .58, loop: false, tracks: [makeTrack('arm-left', 'rotation[x]', [-.14, -.55, -.58, -.52, -.5]), makeTrack('arm-right', 'rotation[x]', [-.14, -.72, -.78, -.65, -.6]), makeTrack('provisional-articulated-rig', 'rotation[z]', [0, .05, .055, .025, 0])] },
    hit: { duration: .28, loop: false, tracks: [makeTrack('arm-left', 'rotation[x]', [0, .32, .18, 0, 0]), makeTrack('arm-right', 'rotation[x]', [0, .32, .18, 0, 0]), makeTrack('provisional-articulated-rig', 'rotation[z]', [0, .12, -.06, 0, 0])] },
    defeat: { duration: 1.2, loop: false, tracks: [makeTrack('leg-left', 'rotation[x]', [0, .14, .56, 1.1, 1.25]), makeTrack('leg-right', 'rotation[x]', [0, .16, .42, .8, .9]), makeTrack('provisional-articulated-rig', 'rotation[z]', [0, .08, .28, 1.05, 1.3]), makeTrack('provisional-articulated-rig', 'position[y]', [0, -.08, -.32, -.66, -.72])] },
    fly: { duration: 1, tracks: [makeTrack('leg-left', 'rotation[x]', [-.18, -.2, -.18, -.16, -.18]), makeTrack('leg-right', 'rotation[x]', [-.18, -.16, -.18, -.2, -.18]), makeTrack('arm-left', 'rotation[x]', [-.9, -.86, -.9, -.94, -.9]), makeTrack('arm-right', 'rotation[x]', [-.9, -.94, -.9, -.86, -.9]), makeTrack('provisional-articulated-rig', 'position[y]', [.06, .1, .14, .1, .06]), makeTrack('provisional-articulated-rig', 'rotation[z]', [-.02, 0, .02, 0, -.02]) ] },
  };
  for (const pose of Object.keys(clipData) as HeroPose[]) {
    const data = clipData[pose];
    for (const track of data.tracks) track.times = Float32Array.from(track.times, value => value * data.duration);
    const action = mixer.clipAction(new THREE.AnimationClip(`hero-${pose}`, data.duration, data.tracks));
    action.setLoop(data.loop === false ? THREE.LoopOnce : THREE.LoopRepeat, data.loop === false ? 1 : Infinity);
    action.clampWhenFinished = data.loop === false;
    clips.set(pose, action);
  }
  let activePose: HeroPose = 'idle';
  let activeAction = clips.get(activePose)!;
  activeAction.play();
  return {
    root,
    spellPoint,
    update(time, delta, pose, speed = 0) {
      if (pose !== activePose) {
        const next = clips.get(pose)!;
        activeAction.fadeOut(.16);
        next.reset().fadeIn(.16).play();
        activeAction = next; activePose = pose;
      }
      if (pose === 'walk') activeAction.timeScale = THREE.MathUtils.clamp(speed / 4.1, .58, 1.32);
      else if (pose === 'run') activeAction.timeScale = THREE.MathUtils.clamp(speed / 7.1, .72, 1.25);
      else activeAction.timeScale = 1;
      mixer.update(delta);
      root.rotation.y = smoothAngle(root.rotation.y, root.userData.facing ?? root.rotation.y, 1 - Math.exp(-delta * 13));
      focus.scale.setScalar(.93 + Math.sin(time * 1.8) * .08);
    },
  };
}
