import * as THREE from 'three';

export type WorldCollider = { x: number; z: number; radius: number };
export type WorldParts = { ground: THREE.Mesh; blockers: THREE.Object3D[]; colliders: WorldCollider[]; rune: THREE.Group };
export type WorldQuality = 'Baixa' | 'Média' | 'Alta';

const COLORS = ['#4d7356', '#66855e', '#82956a', '#506c64', '#758b58'];
const GRASS_COLORS = ['#c2da98', '#d4d39a', '#b2d2a2', '#d3d7a1', '#b8d08a'];
const temp = new THREE.Object3D();

function seeded(n: number) {
  const value = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return value - Math.floor(value);
}

export function terrainHeight(x: number, z: number) {
  const meadowFade = THREE.MathUtils.smoothstep(Math.hypot(x * .72, z + 1) - 12, 0, 24);
  const hills = Math.max(0, Math.sin(x * .036 + 1.2) * Math.cos(z * .029) + Math.sin(z * .052) * .28);
  const rolling = hills * 3.2 + Math.sin(x * .09) * Math.cos(z * .07) * .26;
  return rolling * meadowFade;
}

function makeRibbon(points: THREE.Vector3[], widths: number[], material: THREE.Material) {
  const vertices: number[] = [];
  const indices: number[] = [];
  points.forEach((point, index) => {
    const before = points[Math.max(0, index - 1)];
    const after = points[Math.min(points.length - 1, index + 1)];
    const tangent = after.clone().sub(before).normalize();
    const side = new THREE.Vector3(-tangent.z, 0, tangent.x).multiplyScalar(widths[index] / 2);
    const left = point.clone().add(side);
    const right = point.clone().sub(side);
    left.y = terrainHeight(left.x, left.z) + .035;
    right.y = terrainHeight(right.x, right.z) + .035;
    vertices.push(left.x, left.y, left.z, right.x, right.y, right.z);
    if (index < points.length - 1) {
      const i = index * 2;
      indices.push(i, i + 1, i + 2, i + 1, i + 3, i + 2);
    }
  });
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return new THREE.Mesh(geometry, material);
}

function makeDistantRidge(z: number, height: number, color: string, phase: number) {
  const vertices: number[] = [], indices: number[] = [];
  const segments = 100;
  for (let i = 0; i <= segments; i++) {
    const x = -150 + i / segments * 300;
    const peak = 5 + Math.max(0, Math.sin(x * .047 + phase) * .56 + Math.sin(x * .103 - phase * 1.7) * .28 + Math.sin(x * .021) * .16) * height;
    vertices.push(x, -8, z, x, peak, z);
    if (i < segments) { const n = i * 2; indices.push(n, n + 1, n + 2, n + 1, n + 3, n + 2); }
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3)); geometry.setIndex(indices); geometry.computeVertexNormals();
  const material = new THREE.MeshStandardMaterial({ color, roughness: 1, side: THREE.DoubleSide, flatShading: true });
  const ridge = new THREE.Mesh(geometry, material); ridge.name = 'distant-mountain-ridge'; ridge.receiveShadow = true;
  return ridge;
}

function makeLandmark(scene: THREE.Scene) {
  const group = new THREE.Group();
  group.name = 'hero-marker';
  group.position.set(0, terrainHeight(0, -12), -12);
  const stone = new THREE.MeshStandardMaterial({ color: '#aaa58f', roughness: .88 });
  const shadowStone = new THREE.MeshStandardMaterial({ color: '#696f66', roughness: .94 });
  const gold = new THREE.MeshStandardMaterial({ color: '#d8c38e', roughness: .46, metalness: .28, emissive: '#685532', emissiveIntensity: .18 });
  const base = new THREE.Mesh(new THREE.CylinderGeometry(2.1, 2.32, .42, 12), shadowStone);
  base.position.y = .2; base.receiveShadow = true; group.add(base);
  const step = new THREE.Mesh(new THREE.CylinderGeometry(1.7, 1.9, .2, 12), stone);
  step.position.y = .49; step.castShadow = true; group.add(step);
  const shaft = new THREE.Mesh(new THREE.BoxGeometry(1.15, 3.5, .65), stone);
  shaft.position.set(0, 2.32, 0); shaft.rotation.z = -.045; shaft.castShadow = true; shaft.receiveShadow = true; group.add(shaft);
  const bevel = new THREE.Mesh(new THREE.BoxGeometry(1.42, .16, .82), shadowStone);
  bevel.position.y = 4.05; bevel.castShadow = true; group.add(bevel);
  const crown = new THREE.Mesh(new THREE.ConeGeometry(.82, .72, 4), stone);
  crown.position.y = 4.47; crown.rotation.y = Math.PI / 4; crown.castShadow = true; group.add(crown);
  const medallion = new THREE.Mesh(new THREE.TorusGeometry(.31, .045, 10, 36), gold);
  medallion.position.set(0, 2.55, .36); group.add(medallion);
  const inset = new THREE.Mesh(new THREE.OctahedronGeometry(.15, 0), gold);
  inset.position.set(0, 2.55, .42); group.add(inset);
  const rune = new THREE.Group();
  rune.name = 'marker-rune';
  rune.position.set(0, 2.55, .58);
  for (let i = 0; i < 5; i++) {
    const fleck = new THREE.Mesh(new THREE.SphereGeometry(.035, 8, 6), new THREE.MeshBasicMaterial({ color: '#f4dfaa' }));
    const a = (i / 5) * Math.PI * 2;
    fleck.position.set(Math.cos(a) * .68, Math.sin(a) * .54, 0);
    rune.add(fleck);
  }
  group.add(rune);
  const stoneLight = new THREE.PointLight('#d9c78e', .65, 8, 2);
  stoneLight.position.set(0, 2.8, 1.3); group.add(stoneLight);
  scene.add(group);
  return { group, rune };
}

export function createWorld(scene: THREE.Scene): WorldParts {
  const groundGeometry = new THREE.PlaneGeometry(260, 260, 150, 150);
  const positions = groundGeometry.attributes.position;
  for (let i = 0; i < positions.count; i++) {
    const x = positions.getX(i), z = -positions.getY(i);
    positions.setZ(i, terrainHeight(x, z));
  }
  groundGeometry.computeVertexNormals();
  const groundMaterial = new THREE.MeshStandardMaterial({ color: '#819171', roughness: .96, metalness: 0 });
  groundMaterial.onBeforeCompile = shader => {
    shader.vertexShader = `varying vec3 vMeadowPosition;\n${shader.vertexShader}`.replace('#include <begin_vertex>', '#include <begin_vertex>\nvMeadowPosition = (modelMatrix * vec4(position, 1.0)).xyz;');
    shader.fragmentShader = `varying vec3 vMeadowPosition;\n${shader.fragmentShader}`.replace('#include <color_fragment>', `#include <color_fragment>
      float broad = sin(vMeadowPosition.x * .19 + sin(vMeadowPosition.z * .13)) * cos(vMeadowPosition.z * .16);
      float fine = sin(vMeadowPosition.x * 2.7 + vMeadowPosition.z * 1.9) * cos(vMeadowPosition.z * 2.4 - vMeadowPosition.x * .7);
      float mineral = smoothstep(.72, .96, sin(vMeadowPosition.x * .41) * cos(vMeadowPosition.z * .37));
      diffuseColor.rgb *= 0.96 + broad * .055 + fine * .018;
      diffuseColor.rgb = mix(diffuseColor.rgb, diffuseColor.rgb * vec3(.77, .79, .69), mineral * .14);`);
    groundMaterial.customProgramCacheKey = () => 'aurora-pbr-meadow-v2';
  };
  const ground = new THREE.Mesh(groundGeometry, groundMaterial);
  ground.name = 'ground'; ground.rotation.x = -Math.PI / 2; ground.receiveShadow = true; scene.add(ground);

  const skyMaterial = new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false, fog: false,
    uniforms: { uDaylight: { value: .18 }, uDusk: { value: 1 } },
    vertexShader: `varying float vSkyHeight; void main(){vSkyHeight=normalize(position).y;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
    fragmentShader: `uniform float uDaylight;uniform float uDusk;varying float vSkyHeight;void main(){float h=smoothstep(-.28,.78,vSkyHeight);vec3 night=vec3(.09,.13,.2);vec3 dawn=vec3(.82,.57,.48);vec3 day=vec3(.57,.72,.79);vec3 horizon=mix(night,dawn,uDusk);horizon=mix(horizon,day,uDaylight);vec3 zenith=mix(vec3(.12,.18,.27),vec3(.39,.58,.69),uDaylight);gl_FragColor=vec4(mix(horizon,zenith,pow(h,.72)),1.0);}`,
  });
  const skyDome = new THREE.Mesh(new THREE.SphereGeometry(220, 40, 24), skyMaterial);
  skyDome.name = 'atmosphere-sky-dome'; skyDome.frustumCulled = false; skyDome.renderOrder = -1000; scene.add(skyDome);
  const sunDisc = new THREE.Mesh(new THREE.SphereGeometry(2.7, 24, 16), new THREE.MeshBasicMaterial({ color: '#ffe0ad', fog: false }));
  sunDisc.name = 'soft-sun-disc'; scene.add(sunDisc);
  scene.add(makeDistantRidge(-132, 24, '#697b78', .6), makeDistantRidge(-154, 32, '#72817f', 2.1), makeDistantRidge(-177, 39, '#7c8984', 4.3));

  const blockers: THREE.Object3D[] = [];
  const colliders: WorldCollider[] = [];
  const trunkGeometry = new THREE.CylinderGeometry(.18, .32, 1, 9, 1);
  const leafGeometry = new THREE.SphereGeometry(1, 14, 11);
  const trunkMaterial = new THREE.MeshStandardMaterial({ color: '#74543a', roughness: .94 });
  const leafMaterials = COLORS.map(color => new THREE.MeshStandardMaterial({ color, roughness: .94 }));
  const trunkCount = 96;
  const trunks = new THREE.InstancedMesh(trunkGeometry, trunkMaterial, trunkCount);
  trunks.castShadow = true; trunks.receiveShadow = true; trunks.name = 'forest-trunks';
  const canopies = leafMaterials.map((material, index) => {
    const mesh = new THREE.InstancedMesh(leafGeometry, material, trunkCount * 6);
    mesh.castShadow = true; mesh.receiveShadow = true; mesh.name = `canopy-${index}`; scene.add(mesh); return mesh;
  });
  const canopyCounts = Array(canopies.length).fill(0) as number[];
  let treeIndex = 0;
  for (let i = 0; i < trunkCount; i++) {
    const angle = seeded(i + 3) * Math.PI * 2;
    const radius = 18 + seeded(i + 90) * 48;
    const x = Math.cos(angle) * radius, z = Math.sin(angle) * radius;
    if (Math.abs(x) < 12 && z > -22 && z < 12) continue;
    const scale = .78 + seeded(i + 14) * .74;
    const y = terrainHeight(x, z);
    temp.position.set(x, y + 2.05 * scale, z); temp.scale.set(scale, 4.1 * scale, scale); temp.rotation.y = seeded(i + 500) * Math.PI; temp.updateMatrix(); trunks.setMatrixAt(treeIndex, temp.matrix);
    const crownShapes = [[0, 3.15, 0, 1.24], [-.73, 3.46, .13, .91], [.73, 3.53, -.13, .92], [-.3, 4.1, .1, .78], [.42, 4.18, -.12, .8], [.05, 4.72, 0, .56]];
    for (let layer = 0; layer < crownShapes.length; layer++) {
      const [offsetX, offsetY, offsetZ, size] = crownShapes[layer];
      const crownScale = size * scale;
      temp.position.set(x + offsetX * scale, y + offsetY * scale, z + offsetZ * scale);
      temp.scale.set(crownScale, crownScale * 1.16, crownScale * .94); temp.rotation.set(0, seeded(i + layer * 19) * Math.PI * 2, 0); temp.updateMatrix();
      const colorIndex = (i + layer) % leafMaterials.length;
      canopies[colorIndex].setMatrixAt(canopyCounts[colorIndex]++, temp.matrix);
    }
    colliders.push({ x, z, radius: .64 * scale });
    treeIndex++;
  }
  trunks.count = treeIndex;
  trunks.instanceMatrix.needsUpdate = true; scene.add(trunks); blockers.push(trunks);
  for (let i = 0; i < canopies.length; i++) { canopies[i].count = canopyCounts[i]; canopies[i].instanceMatrix.needsUpdate = true; }

  const rockGeometry = new THREE.DodecahedronGeometry(1, 1);
  const rockMaterial = new THREE.MeshStandardMaterial({ color: '#838477', roughness: .97, flatShading: true });
  const rocks = new THREE.InstancedMesh(rockGeometry, rockMaterial, 46);
  rocks.castShadow = true; rocks.receiveShadow = true; rocks.name = 'field-stones';
  let rockCount = 0;
  for (let i = 0; i < 46; i++) {
    const x = (seeded(300 + i) - .5) * 88, z = (seeded(500 + i) - .5) * 82;
    if (Math.abs(x) < 6 && z > -18 && z < 7) continue;
    const size = .32 + seeded(700 + i) * .9;
    temp.position.set(x, terrainHeight(x, z) + size * .38, z); temp.scale.set(size, size * .68, size * .82); temp.rotation.set(.1, seeded(900 + i) * 6, .13); temp.updateMatrix(); rocks.setMatrixAt(rockCount++, temp.matrix);
    colliders.push({ x, z, radius: size * .85 });
  }
  rocks.count = rockCount; rocks.instanceMatrix.needsUpdate = true; scene.add(rocks); blockers.push(rocks);

  const grassGeometry = new THREE.BufferGeometry();
  const grassVertices: number[] = [];
  const grassIndices: number[] = [];
  for (let blade = 0; blade < 4; blade++) {
    const angle = blade * Math.PI / 4;
    const sideX = Math.cos(angle) * .035, sideZ = Math.sin(angle) * .035;
    const tipX = Math.cos(angle + .72) * .1, tipZ = Math.sin(angle + .72) * .1;
    const start = grassVertices.length / 3;
    grassVertices.push(-sideX, 0, -sideZ, sideX, 0, sideZ, tipX, .34 + (blade % 2) * .08, tipZ);
    grassIndices.push(start, start + 1, start + 2);
  }
  grassGeometry.setAttribute('position', new THREE.Float32BufferAttribute(grassVertices, 3)); grassGeometry.setIndex(grassIndices); grassGeometry.computeVertexNormals();
  const grassMaterial = new THREE.MeshBasicMaterial({ color: '#ffffff', side: THREE.DoubleSide });
  grassMaterial.onBeforeCompile = shader => {
    shader.uniforms.uWindTime = { value: 0 };
    shader.vertexShader = `uniform float uWindTime;\n${shader.vertexShader}`.replace('#include <begin_vertex>', '#include <begin_vertex>\ntransformed.x += sin(uWindTime + instanceMatrix[3].x * 0.17 + position.y * 2.0) * 0.12 * position.y;');
    grassMaterial.userData.windUniform = shader.uniforms.uWindTime;
  };
  grassMaterial.customProgramCacheKey = () => 'aurora-grass-wind-v1';
  const grass = new THREE.InstancedMesh(grassGeometry, grassMaterial, 2800);
  grass.name = 'wind-grass'; grass.castShadow = false; grass.receiveShadow = true;
  let grassCount = 0;
  for (let i = 0; i < 2800; i++) {
    const x = (seeded(1200 + i) - .5) * 44, z = (seeded(1600 + i) - .5) * 40;
    if ((Math.abs(x) < 3.2 && z > -17 && z < 7) || Math.hypot(x, z + 12) < 2.8) continue;
    const scale = .62 + seeded(1900 + i) * .78;
    temp.position.set(x, terrainHeight(x, z), z); temp.scale.set(scale, scale, scale); temp.rotation.y = seeded(2200 + i) * Math.PI; temp.updateMatrix(); grass.setMatrixAt(grassCount, temp.matrix);
    grass.setColorAt(grassCount, new THREE.Color(GRASS_COLORS[i % GRASS_COLORS.length])); grassCount++;
  }
  grass.count = grassCount; grass.userData.maxInstances = grassCount; grass.instanceMatrix.needsUpdate = true; if (grass.instanceColor) grass.instanceColor.needsUpdate = true; scene.add(grass);

  const motePositions: number[] = [];
  for (let i = 0; i < 74; i++) motePositions.push((seeded(3200 + i) - .5) * 54, 1.2 + seeded(3400 + i) * 4.2, (seeded(3600 + i) - .5) * 54);
  const moteGeometry = new THREE.BufferGeometry(); moteGeometry.setAttribute('position', new THREE.Float32BufferAttribute(motePositions, 3));
  const moteMaterial = new THREE.PointsMaterial({ color: '#e7d9a8', size: .085, transparent: true, opacity: .53, depthWrite: false, sizeAttenuation: true });
  moteMaterial.onBeforeCompile = shader => {
    shader.uniforms.uMoteTime = { value: 0 };
    shader.vertexShader = `uniform float uMoteTime;\n${shader.vertexShader}`.replace('#include <begin_vertex>', '#include <begin_vertex>\ntransformed.y += sin(uMoteTime * 0.65 + position.x * 0.29 + position.z * 0.2) * 0.16;');
    moteMaterial.userData.timeUniform = shader.uniforms.uMoteTime;
  };
  moteMaterial.customProgramCacheKey = () => 'aurora-motes-v1';
  const motes = new THREE.Points(moteGeometry, moteMaterial); motes.name = 'windborne-echoes'; scene.add(motes);

  const flowerGeometry = new THREE.SphereGeometry(.055, 7, 6);
  const flowerMaterials = ['#e8d7a6', '#d89f98', '#e4e0c6'].map(color => new THREE.MeshBasicMaterial({ color }));
  const flowers = flowerMaterials.map((material, i) => {
    const mesh = new THREE.InstancedMesh(flowerGeometry, material, 130); mesh.name = `meadow-blooms-${i}`;
    let count = 0;
    for (let j = 0; j < 130; j++) {
      const x = (seeded(2500 + j) - .5) * 24, z = (seeded(2700 + j) - .5) * 25;
      if ((Math.abs(x) < 4 && z > -18 && z < 7) || j % 3 !== i) continue;
      temp.position.set(x, terrainHeight(x, z) + .3, z); const size = .65 + seeded(2900 + j) * .8; temp.scale.setScalar(size); temp.updateMatrix(); mesh.setMatrixAt(count++, temp.matrix);
    }
    mesh.count = count; mesh.userData.maxInstances = count; mesh.instanceMatrix.needsUpdate = true; scene.add(mesh); return mesh;
  });

  const pathMaterial = new THREE.MeshStandardMaterial({ color: '#a59471', roughness: 1, side: THREE.DoubleSide });
  const pathPoints: THREE.Vector3[] = [];
  const widths: number[] = [];
  for (let i = 0; i <= 30; i++) {
    const t = i / 30;
    const z = 10 - t * 31;
    const x = Math.sin(t * Math.PI * 1.15) * 1.5;
    pathPoints.push(new THREE.Vector3(x, 0, z)); widths.push(3.2 + Math.sin(t * Math.PI) * .45);
  }
  const path = makeRibbon(pathPoints, widths, pathMaterial); path.name = 'waystone-trail'; path.receiveShadow = true; scene.add(path);

  const ruin = new THREE.Group(); ruin.name = 'fallen-arch'; ruin.position.set(-12, terrainHeight(-12, -21), -21);
  const ruinStone = new THREE.MeshStandardMaterial({ color: '#888b7c', roughness: .92 });
  const left = new THREE.Mesh(new THREE.BoxGeometry(.65, 3.4, .7), ruinStone); left.position.set(-1.6, 1.7, 0); left.rotation.z = -.08; left.castShadow = true; ruin.add(left);
  const right = new THREE.Mesh(new THREE.BoxGeometry(.65, 2.3, .7), ruinStone); right.position.set(1.6, 1.15, 0); right.rotation.z = .12; right.castShadow = true; ruin.add(right);
  const lintel = new THREE.Mesh(new THREE.BoxGeometry(4.1, .55, .8), ruinStone); lintel.position.set(0, 3.35, 0); lintel.rotation.z = .045; lintel.castShadow = true; ruin.add(lintel);
  const fallen = new THREE.Mesh(new THREE.BoxGeometry(1.7, .4, .65), ruinStone); fallen.position.set(2.5, .2, 1.3); fallen.rotation.z = .23; fallen.castShadow = true; ruin.add(fallen);
  scene.add(ruin); blockers.push(ruin); colliders.push({ x: -13.6, z: -21, radius: .65 }, { x: -10.4, z: -21, radius: .65 });

  const { group: landmark, rune } = makeLandmark(scene);
  blockers.push(landmark);
  colliders.push({ x: 0, z: -12, radius: 2.05 });
  scene.userData.environment = { grassMaterial, flowers, moteMaterial, grass, bloomMeshes: flowers, skyMaterial, sunDisc };
  return { ground, blockers, colliders, rune };
}

export function setWorldQuality(scene: THREE.Scene, quality: WorldQuality) {
  const environment = scene.userData.environment;
  if (!environment) return;
  const grass = environment.grass as THREE.InstancedMesh;
  const blooms = environment.bloomMeshes as THREE.InstancedMesh[];
  const grassMax = grass.userData.maxInstances as number;
  grass.count = quality === 'Baixa' ? Math.floor(grassMax * .35) : quality === 'Média' ? Math.floor(grassMax * .68) : grassMax;
  for (const bloom of blooms) {
    const max = bloom.userData.maxInstances as number | undefined;
    if (max === undefined) bloom.userData.maxInstances = bloom.count;
    const count = (bloom.userData.maxInstances as number) * (quality === 'Baixa' ? .35 : quality === 'Média' ? .68 : 1);
    bloom.count = Math.floor(count);
  }
}

export function updateWorld(parts: WorldParts, time: number) {
  parts.rune.rotation.z = Math.sin(time * .7) * .06;
  const env = parts.ground.parent?.userData.environment;
  const uniform = env?.grassMaterial?.userData.windUniform as { value: number } | undefined;
  if (uniform) uniform.value = time;
  const moteTime = env?.moteMaterial?.userData.timeUniform as { value: number } | undefined;
  if (moteTime) moteTime.value = time;
}

const cycleSky = new THREE.Color();
const cycleDawn = new THREE.Color('#e6ac91');
const cycleDay = new THREE.Color('#9fb9c4');
const cycleNight = new THREE.Color('#263346');
const cycleSunset = new THREE.Color('#f6b690');
const cycleSkyColor = new THREE.Color('#a9c4d4');
const cycleGroundDay = new THREE.Color('#687451');
const cycleFogDay = new THREE.Color('#a1ad99');

export function updateDayCycle(scene: THREE.Scene, sun: THREE.DirectionalLight, sky: THREE.HemisphereLight, time: number) {
  const phase = (time / 240) * Math.PI * 2;
  const sunArc = Math.sin(phase);
  const daylight = THREE.MathUtils.smoothstep(sunArc, -.08, .42);
  const dusk = Math.max(0, 1 - Math.abs(sunArc) * 3.2);
  sun.position.set(Math.cos(phase) * 46, 14 + sunArc * 43, Math.sin(phase * .5) * 19);
  sun.intensity = .16 + daylight * 2.72;
  sun.color.set('#fff0d9').lerp(cycleSunset, dusk * .55);
  sky.intensity = .52 + daylight * 1.45;
  sky.color.copy(cycleSkyColor).lerp(cycleDawn, dusk * .42);
  sky.groundColor.set('#26303d').lerp(cycleGroundDay, daylight * .62);
  cycleSky.copy(cycleNight).lerp(cycleDawn, Math.max(dusk, .06)).lerp(cycleDay, daylight);
  if (scene.background instanceof THREE.Color) scene.background.copy(cycleSky);
  if (scene.fog instanceof THREE.FogExp2) scene.fog.color.copy(cycleSky).lerp(cycleFogDay, daylight * .24);
  const environment = scene.userData.environment;
  const skyUniforms = environment?.skyMaterial?.uniforms;
  if (skyUniforms) { skyUniforms.uDaylight.value = daylight; skyUniforms.uDusk.value = dusk; }
  const sunDisc = environment?.sunDisc as THREE.Mesh | undefined;
  if (sunDisc) { sunDisc.position.copy(sun.position).normalize().multiplyScalar(168); sunDisc.visible = sunArc > -.1; }
  const hour = Math.floor(((time / 240) * 24 + 6) % 24);
  return { label: `${String(hour).padStart(2, '0')}:00`, daylight };
}
